/* ---- growing buffers (malloc; for building texts) ---- */
typedef struct FcBuf { char* p; size_t len, cap; } FcBuf;
void fcBufPut(FcBuf* b, const char* s, size_t n);
void fcBufStr(FcBuf* b, const char* s);
void fcBufChar(FcBuf* b, char c);
void fcBufFmt(FcBuf* b, const char* fmt, ...);
void fcBufUnit(FcBuf* b, uint16_t unit);   /* one UTF-16 unit as fc8 */
void fcBufFree(FcBuf* b);

typedef struct FcU16 { uint16_t* p; int len, cap; } FcU16;   /* UTF-16 units (malloc) */
void fcU16Put(FcU16* b, const uint16_t* s, int n);
void fcU16Unit(FcU16* b, uint16_t c);
void fcU16Free(FcU16* b);

/* ---- lists (in the arena of the context): NULL is C#'s null, an empty list is a list ---- */
struct FcList { void** items; int count, cap; bool own; };   /* own: an OwnNamespaceList (TypeRef.Namespaces) */

/* ---- exceptions: the C# throw/catch/finally, on the context ---- */
/* FC_ERR_RESOLVE: a ResolverException (one: message, line, source; the combined one of Resolver.Resolve: `list` of FcError*); FC_ERR_TYPECHECK: a
 * TypeCheckException (`list` of FcDiagnostic*); FC_ERR_LINKER: an exception of the linker (CompileDiagnostics.Of: its message, area Linker) */
typedef enum FcErrKind { FC_ERR_NONE, FC_ERR_LEX, FC_ERR_PRE, FC_ERR_PARSE, FC_ERR_INTERNAL, FC_ERR_RESOLVE, FC_ERR_TYPECHECK, FC_ERR_LINKER, FC_ERR_COMPILE, FC_ERR_NOTSUPPORTED, FC_ERR_MARKUP, FC_ERR_NATIVE, FC_ERR_PROJECT, FC_ERR_PACKAGE } FcErrKind;   /* FC_ERR_NATIVE: NativeNotSupportedException of the generator (gen/) */
typedef struct FcList FcList;
typedef struct FcError { FcErrKind kind; const char* message; int line, column; const char* file; int source; FcList* list; } FcError;
typedef struct FcTry { jmp_buf jb; struct FcTry* prev; } FcTry;

/* ---- diagnostics (Diagnostics.cs) ---- */
typedef enum FcSeverity { FC_SEV_ERROR, FC_SEV_WARNING } FcSeverity;
typedef struct FcDiagnostic { int line; const char* message; FcSeverity severity; const char* code; const char* file; int column; } FcDiagnostic;
typedef enum FcWarnTarget { FC_WARN_CLASS, FC_WARN_CONSTRUCTOR, FC_WARN_METHOD, FC_WARN_MEMBER } FcWarnTarget;
typedef struct FcDeclaredWarning { const char* cls; FcWarnTarget target; const char* name; int minArity, maxArity; bool isStatic; int id; const char* text; int line; const char* file; } FcDeclaredWarning;
typedef enum FcArea { FC_AREA_LEXER, FC_AREA_PREPROCESSOR, FC_AREA_PARSER, FC_AREA_RESOLVER, FC_AREA_COMPILER, FC_AREA_LINKER, FC_AREA_NATIVE } FcArea;
typedef struct FcCatalogEntry { const char* code; FcArea area; int literalLength; int partCount; const char** parts; } FcCatalogEntry;

typedef struct FcCustomUnit FcCustomUnit;

typedef struct FcCtx FcCtx;
struct FcCtx {
    FbArena arena;
    FcTry* tryTop;
    FcError err;
    /* DirectiveRegistry.Symbols (case-insensitive: kept in lower case) */
    FcList* symbols;
    /* DiagnosticCollector: active when `collecting` */
    bool collecting;
    FcList* diags;      /* FcDiagnostic* */
    FcList* declared;   /* FcDeclaredWarning* */
    /* ErrorCatalog, made on first use */
    FcCatalogEntry* catalog;
    int catalogCount;
    /* the units of the program (Unit.UseCustomUnits) */
    FcList* customUnits;   /* FcCustomUnit* in the order of their declarations */
    FbMap customTable;     /* symbol and name -> FcCustomUnit* */
    /* Parser._declaredNamespaces */
    FbMap declaredNamespaces;
    FbMap unitWords;       /* Parser.DefineUnits: the symbols and names of the declared units */
    bool hasDeclaredNamespaces;
    /* Parser.SourceImportNamespaces: by the index of a source, its import namespaces (NULL: none) */
    FcList* sourceImportNamespaces;
    /* the qualifier of each source (ProcessedSource.Qualify), set by the linker before ParseMultiple; NULL: none */
    /* the linker (Phase C 3): the set of included files shared by all sources of a program (NULL: one per source), the effects of its directives */
    FcList* sharedIncluded;
    void (*directiveHook)(struct FcCtx* c, void* state, const char* name, FcList* args, int line, FcList* importNamespaces);
    int programWordWidth;   /* TypeChecker.ProgramWordWidth of the target (0: 64; the generator, Phase D 1, sets it) */
    void* directiveState;
    /* the ResourceTable of `new Resource("path")` (Preprocessor.ResolveResources): the full paths, a resource's id is its index; NULL: none */
    FcList* resourcePaths;
    FcList* resourceNames;   /* the names as written (ResourceEntry.Name), parallel to resourcePaths */
    void* modelResources;    /* (Phase D 4, model/command.c) the model files of the model resources converted so far */
    /* Linker.TestDriver (`forge test`, Phase D 4, tools/testdriver.c): the source of the test driver for the parsed program; NULL: none */
    const char* (*testDriver)(struct FcCtx* c, void* state, FcList* program, int firstUserSource);
    void* testDriverState;
    /* the markup generators (Phase C 5): the schema of the elements, made on first use (markupschema.c) */
    void* markupSchema;
};

void fcCtxInit(FcCtx* c);

/* the model resources (Phase D 4, model/command.c): ResourceTable.Add converts a glTF, .fblocks or .fmesh resource into fire's model file when it is
 * added (an error is the preprocessor's); the linker reads every resource through fcResourceRead (malloc'd: the model file of a model, else the file) */
void fcResourceAdded(FcCtx* c, const char* fullPath, const char* name);
uint8_t* fcResourceRead(FcCtx* c, const char* fullPath, size_t* n);
