/* ---- native/forge/conditional.c ---- */
/* native/forge/conditional.c - port of src/fire.Compiler/Conditional.cs (commit 8bfb232a): ConditionalSymbols (For, Evaluate), InlineCScan,
 * ConditionalState. Texts of a line are UTF-16 units (FcSlice). The symbols are case-insensitive: they are kept in lower case. */

typedef struct FcSlice { const uint16_t* p; int n; } FcSlice;

static FcSlice fcSliceTrim(FcSlice s) {
    while (s.n > 0 && fcIsWhiteSpace(s.p[0])) { s.p++; s.n--; }
    while (s.n > 0 && fcIsWhiteSpace(s.p[s.n - 1])) s.n--;
    return s;
}
static FcSlice fcSliceTrimStart(FcSlice s) {
    while (s.n > 0 && fcIsWhiteSpace(s.p[0])) { s.p++; s.n--; }
    return s;
}
static const char* fcSliceText(FcCtx* c, FcSlice s) { return fc8FromU16(c, s.p, s.n); }

static const char* fcLower(FcCtx* c, const char* s) {
    char* d = (char*)fcStr(c, s);
    char* p;
    for (p = d; *p; p++) if (*p >= 'A' && *p <= 'Z') *p = (char)(*p - 'A' + 'a');
    return d;
}

/* the set of symbols (case-insensitive) */
static int fcSymbolIndex(FcCtx* c, FcList* symbols, const char* name) {
    const char* low = fcLower(c, name);
    int i;
    for (i = 0; i < symbols->count; i++) if (strcmp((const char*)symbols->items[i], low) == 0) return i;
    return -1;
}
bool fcSymbolsContains(FcCtx* c, FcList* symbols, const char* name) { return fcSymbolIndex(c, symbols, name) >= 0; }
void fcSymbolsAdd(FcCtx* c, FcList* symbols, const char* name) {
    if (fcSymbolIndex(c, symbols, name) < 0) fcListAdd(c, symbols, (void*)fcLower(c, name));
}
static void fcSymbolsRemove(FcCtx* c, FcList* symbols, const char* name) {
    int i = fcSymbolIndex(c, symbols, name);
    if (i >= 0) fcListRemoveAt(symbols, i);
}

/* ConditionalSymbols.For(null, "vm"): the symbols of a VM run on this machine (TargetProfile.Host: 64-bit int and float, the word of 64 bits) */
void fcSymbolsForHost(FcCtx* c, FcList* symbols) {
#if defined(_WIN32)
    fcSymbolsAdd(c, symbols, "windows");
#elif defined(__APPLE__)
    fcSymbolsAdd(c, symbols, "macos");
    fcSymbolsAdd(c, symbols, "posix");
#else
    fcSymbolsAdd(c, symbols, "linux");
    fcSymbolsAdd(c, symbols, "posix");
#endif
    fcSymbolsAdd(c, symbols, "vm");
    fcSymbolsAdd(c, symbols, "word64");
}

static bool fcIsNameStart(uint16_t c) { return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_'; }
static bool fcIsNamePart(uint16_t c) { return fcIsNameStart(c) || (c >= '0' && c <= '9'); }

/* `^[A-Za-z_][A-Za-z0-9_]*$` */
static bool fcNameOnly(FcSlice s) {
    int i;
    if (s.n == 0 || !fcIsNameStart(s.p[0])) return false;
    for (i = 1; i < s.n; i++) if (!fcIsNamePart(s.p[i])) return false;
    return true;
}

typedef struct FcEval { FcCtx* ctx; const char** tokens; int count, i; FcList* symbols; int line; const char* trimmed; } FcEval;

_Noreturn static void fcPreError(FcCtx* c, const char* message) { fcThrow(c, FC_ERR_PRE, 0, 0, NULL, message); }

static bool fcEvalOr(FcEval* e);
static bool fcEvalPrimary(FcEval* e) {
    const char* t;
    if (e->i >= e->count) fcPreError(e->ctx, fcFmt(e->ctx, "'#if' expression '%s' ends too early (line %d).", e->trimmed, e->line));
    t = e->tokens[e->i++];
    if (strcmp(t, "(") == 0) {
        bool v = fcEvalOr(e);
        if (e->i >= e->count || strcmp(e->tokens[e->i], ")") != 0)
            fcPreError(e->ctx, fcFmt(e->ctx, "'#if' expression '%s': ')' is missing (line %d).", e->trimmed, e->line));
        e->i++;
        return v;
    }
    if (strcmp(t, ")") == 0 || strcmp(t, "&&") == 0 || strcmp(t, "||") == 0)
        fcPreError(e->ctx, fcFmt(e->ctx, "'#if' expression '%s': unexpected '%s' (line %d).", e->trimmed, t, e->line));
    if (strcmp(t, "true") == 0) return true;
    if (strcmp(t, "false") == 0) return false;
    return fcSymbolsContains(e->ctx, e->symbols, t);
}
static bool fcEvalNot(FcEval* e) {
    if (e->i < e->count && strcmp(e->tokens[e->i], "!") == 0) { e->i++; return !fcEvalNot(e); }
    return fcEvalPrimary(e);
}
static bool fcEvalAnd(FcEval* e) {
    bool v = fcEvalNot(e);
    while (e->i < e->count && strcmp(e->tokens[e->i], "&&") == 0) { bool r; e->i++; r = fcEvalNot(e); v = v && r; }
    return v;
}
static bool fcEvalOr(FcEval* e) {
    bool v = fcEvalAnd(e);
    while (e->i < e->count && strcmp(e->tokens[e->i], "||") == 0) { bool r; e->i++; r = fcEvalAnd(e); v = v || r; }
    return v;
}

/* ConditionalSymbols.Evaluate */
bool fcEvaluateCondition(FcCtx* c, FcSlice expression, FcList* symbols, int line) {
    FcEval e;
    const char** tokens = (const char**)fcAlloc(c, sizeof(char*) * (size_t)(expression.n + 1));
    int count = 0, pos = 0;
    while (pos < expression.n) {
        uint16_t ch = expression.p[pos];
        if (fcIsWhiteSpace(ch)) { pos++; continue; }
        if (fcIsNameStart(ch)) {
            int start = pos;
            while (pos < expression.n && fcIsNamePart(expression.p[pos])) pos++;
            tokens[count++] = fc8FromU16(c, expression.p + start, pos - start);
            continue;
        }
        if (ch == '&' && pos + 1 < expression.n && expression.p[pos + 1] == '&') { tokens[count++] = "&&"; pos += 2; continue; }
        if (ch == '|' && pos + 1 < expression.n && expression.p[pos + 1] == '|') { tokens[count++] = "||"; pos += 2; continue; }
        if (ch == '!') { tokens[count++] = "!"; pos++; continue; }
        if (ch == '(') { tokens[count++] = "("; pos++; continue; }
        if (ch == ')') { tokens[count++] = ")"; pos++; continue; }
        fcPreError(c, fcFmt(c, "'#if' expression '%s': unexpected character '%s' (line %d).", fcSliceText(c, fcSliceTrim(expression)),
            fc8FromU16(c, expression.p + pos, 1), line));
    }
    if (count == 0) fcPreError(c, fcFmt(c, "'#if' expects a condition (line %d).", line));
    e.ctx = c; e.tokens = tokens; e.count = count; e.i = 0; e.symbols = symbols; e.line = line;
    e.trimmed = fcSliceText(c, fcSliceTrim(expression));
    {
        bool result = fcEvalOr(&e);
        if (e.i < count) fcPreError(c, fcFmt(c, "'#if' expression '%s': unexpected '%s' (line %d).", e.trimmed, tokens[e.i], line));
        return result;
    }
}

/* ---- InlineCScan ---- */
typedef struct FcInlineCScan { bool armed, blockComment; int parens, depth, waitLines; } FcInlineCScan;

static bool fcInlineInBody(const FcInlineCScan* s) { return s->depth > 0; }

/* `^\s*(?:(?:public|private|protected|static)\s+)*inline\s+c\s+[A-Za-z_]`: the length of the match, -1 for none */
static int fcInlineStart(FcSlice line) {
    static const char* const mods[] = { "public", "private", "protected", "static" };
    int i = 0, k;
    while (i < line.n && fcIsWhiteSpace(line.p[i])) i++;
    for (;;) {
        bool any = false;
        for (k = 0; k < 4; k++) {
            int len = (int)strlen(mods[k]), j;
            if (i + len > line.n) continue;
            for (j = 0; j < len; j++) if (line.p[i + j] != (uint8_t)mods[k][j]) break;
            if (j < len || i + len >= line.n || !fcIsWhiteSpace(line.p[i + len])) continue;
            i += len;
            while (i < line.n && fcIsWhiteSpace(line.p[i])) i++;
            any = true;
            break;
        }
        if (!any) break;
    }
    {
        static const char inl[] = "inline";
        int j;
        if (i + 6 > line.n) return -1;
        for (j = 0; j < 6; j++) if (line.p[i + j] != (uint8_t)inl[j]) return -1;
        i += 6;
        if (i >= line.n || !fcIsWhiteSpace(line.p[i])) return -1;
        while (i < line.n && fcIsWhiteSpace(line.p[i])) i++;
        if (i >= line.n || line.p[i] != 'c') return -1;
        i++;
        if (i >= line.n || !fcIsWhiteSpace(line.p[i])) return -1;
        while (i < line.n && fcIsWhiteSpace(line.p[i])) i++;
        if (i >= line.n || !fcIsNameStart(line.p[i])) return -1;
        return i + 1;
    }
}

static void fcInlineFeed(FcInlineCScan* s, FcSlice line) {
    int i = 0;
    if (!s->armed && s->depth == 0) {
        int m = fcInlineStart(line);
        if (m < 0) return;
        s->armed = true;
        s->parens = 0;
        s->waitLines = 0;
        i = m - 1;
    } else if (s->armed && s->parens <= 0 && s->waitLines++ > 0 && fcSliceTrim(line).n > 0) {
        FcSlice t = fcSliceTrimStart(line);
        if (!(t.n > 0 && t.p[0] == '{')) { s->armed = false; return; }
    }
    for (; i < line.n; i++) {
        uint16_t ch = line.p[i];
        bool slash2 = ch == '/' && i + 1 < line.n && line.p[i + 1] == '/';
        if (s->blockComment) { if (ch == '*' && i + 1 < line.n && line.p[i + 1] == '/') { s->blockComment = false; i++; } continue; }
        if (s->depth == 0) {
            if (ch == '(') s->parens++;
            else if (ch == ')') s->parens--;
            else if (ch == '=' && s->parens <= 0) { s->armed = false; return; }
            else if (ch == '{' && s->parens <= 0) { s->armed = false; s->depth = 1; }
            else if (ch == ';' || slash2) { if (s->parens <= 0) { s->armed = false; return; } }
            continue;
        }
        if (slash2) return;
        if (ch == '/' && i + 1 < line.n && line.p[i + 1] == '*') { s->blockComment = true; i++; continue; }
        if (ch == '"' || ch == '\'') {
            for (i++; i < line.n && line.p[i] != ch; i++) if (line.p[i] == '\\') i++;
            continue;
        }
        if (ch == '{') s->depth++;
        else if (ch == '}' && --s->depth == 0) return;
    }
}

/* ---- ConditionalState ---- */
typedef struct FcCondFrame { bool parentActive, taken, active, sawElse; int line; } FcCondFrame;
typedef struct FcCondState { FcCondFrame* frames; int count, cap; } FcCondState;

static bool fcCondActive(const FcCondState* s) { return s->count == 0 || s->frames[s->count - 1].active; }

static void fcCondPush(FcCondState* s, bool condition, int line) {
    bool parent = fcCondActive(s), v = parent && condition;
    if (s->count == s->cap) {
        s->cap = s->cap ? s->cap * 2 : 8;
        s->frames = (FcCondFrame*)realloc(s->frames, sizeof(FcCondFrame) * (size_t)s->cap);
        if (!s->frames) { fbOutOfMemory(); return; }
    }
    s->frames[s->count].parentActive = parent;
    s->frames[s->count].taken = v;
    s->frames[s->count].active = v;
    s->frames[s->count].sawElse = false;
    s->frames[s->count].line = line;
    s->count++;
}

static bool fcCondNameCondition(FcCtx* c, FcSlice argument, const char* directive, FcList* symbols, int line) {
    if (!fcNameOnly(argument)) fcPreError(c, fcFmt(c, "'#%s' expects a name (line %d).", directive, line));
    return fcSymbolsContains(c, symbols, fcSliceText(c, argument));
}

/* ConditionalState.TryHandle (throwOnError: true - the preprocessor) */
static bool fcCondTryHandle(FcCtx* c, FcCondState* s, const char* name, FcSlice argument, int line, FcList* symbols) {
    const char* low = fcLower(c, name);
    argument = fcSliceTrim(argument);
    if (strcmp(low, "if") == 0) { bool v = fcCondActive(s) && fcEvaluateCondition(c, argument, symbols, line); fcCondPush(s, v, line); return true; }
    if (strcmp(low, "ifdef") == 0) { bool v = fcCondActive(s) && fcCondNameCondition(c, argument, "ifdef", symbols, line); fcCondPush(s, v, line); return true; }
    if (strcmp(low, "ifndef") == 0) { bool v = fcCondActive(s) && !fcCondNameCondition(c, argument, "ifndef", symbols, line); fcCondPush(s, v, line); return true; }
    if (strcmp(low, "elif") == 0) {
        FcCondFrame* f;
        if (s->count == 0) fcPreError(c, fcFmt(c, "'#elif' without '#if' (line %d).", line));
        f = &s->frames[s->count - 1];
        if (f->sawElse) fcPreError(c, fcFmt(c, "'#elif' after '#else' (line %d).", line));
        if (f->parentActive && !f->taken) {
            bool v = fcEvaluateCondition(c, argument, symbols, line);
            f = &s->frames[s->count - 1];
            f->active = v; f->taken = v;
        } else f->active = false;
        return true;
    }
    if (strcmp(low, "else") == 0) {
        FcCondFrame* f;
        if (s->count == 0) fcPreError(c, fcFmt(c, "'#else' without '#if' (line %d).", line));
        f = &s->frames[s->count - 1];
        if (f->sawElse) fcPreError(c, fcFmt(c, "A second '#else' for the '#if' of line %d (line %d).", f->line, line));
        f->sawElse = true;
        f->active = f->parentActive && !f->taken;
        f->taken = true;
        return true;
    }
    if (strcmp(low, "endif") == 0) {
        if (s->count == 0) fcPreError(c, fcFmt(c, "'#endif' without '#if' (line %d).", line));
        s->count--;
        return true;
    }
    if (strcmp(low, "define") == 0 || strcmp(low, "undef") == 0) {
        const char* arg;
        if (!fcCondActive(s)) return true;
        if (!fcNameOnly(argument)) fcPreError(c, fcFmt(c, "'#%s' expects a name (line %d).", name, line));
        arg = fcSliceText(c, argument);
        if (strcmp(low, "define") == 0) fcSymbolsAdd(c, symbols, arg); else fcSymbolsRemove(c, symbols, arg);
        return true;
    }
    if (strcmp(low, "error") == 0) {
        if (fcCondActive(s)) fcPreError(c, fcFmt(c, "#error %s (line %d)", fcSliceText(c, argument), line));
        return true;
    }
    return false;
}

static void fcCondEnsureClosed(FcCtx* c, FcCondState* s) {
    if (s->count > 0) fcPreError(c, fcFmt(c, "The '#if' of line %d has no '#endif'.", s->frames[s->count - 1].line));
}
/* ---- (native/forge/conditional.c ends: native/forge/forge.c) ---- */
/* ---- native/forge/preprocessor.c ---- */
/* native/forge/preprocessor.c - port of src/fire.Compiler/Preprocessor.cs (commit df5ad3c3): Preprocessor, DirectiveRegistry (the default one:
 * `#include` and the directives Linker registers, with their numbers of parameters - without their effects), ProcessedSource. Not ported: the resources of `new Resource("path")` (only with a ResourceTable, which
 * the frontend dumps do not have). A markup file included with `#include` (.fxml, .biscuit, .fdata) is the script its generator makes (Phase C 5). */

typedef struct FcProcessed {
    const uint16_t* source;
    int length;
    FcList* usings;           /* fc8 */
    FcList* importNamespaces; /* fc8 */
    const char* name;
    /* set by the linker (Phase C 3): ProcessedSource.NotSerializable, Module, Qualify */
    bool notSerializable;
    const char* module;
    const char* qualify;
} FcProcessed;

typedef struct FcPreprocessor {
    FcCtx* ctx;
    FcList* includeChain;     /* full paths */
    FcList* usings;
    FcList* importNamespaces;
    FcList* alreadyIncluded;  /* full paths (case-insensitive, as the C# set) */
} FcPreprocessor;

/* the directives of the registry: DirectiveRegistry.CreateDefault (`include` with its handler) and what Linker registers, with the number of
 * parameters (the dumps register them without effects, src/fire.Compiler/FrontendDump.cs LinkerDirectives) - the line of each disappears */
typedef struct FcDirectiveDef { const char* name; int paramCount; } FcDirectiveDef;
static const FcDirectiveDef fcDirectives[] = {
    {"import", 1}, {"include", 1}, {"name", 1}, {"codename", 1}, {"author", 1}, {"comments", 1}, {"description", 1}, {"icon", 1}, {"debug", 0},
    {"performance", 0}, {"floatwidth", 1}, {"noconsole", 0}, {"version", 1}, {"fileversion", 1}, {"intwidth", 1},
};

static bool fcAsciiIEq(const char* a, const char* b) {
    for (; *a && *b; a++, b++) {
        char x = *a, y = *b;
        if (x >= 'A' && x <= 'Z') x = (char)(x - 'A' + 'a');
        if (y >= 'A' && y <= 'Z') y = (char)(y - 'A' + 'a');
        if (x != y) return false;
    }
    return *a == *b;
}
static bool fcListHasIStr(const FcList* l, const char* s) {
    int i;
    for (i = 0; i < l->count; i++) if (fcAsciiIEq((const char*)l->items[i], s)) return true;
    return false;
}

/* `^\s*#([A-Za-z_][A-Za-z0-9_]*)(?:[ \t]+(.*))?\s*$`: false when the line is no directive */
static bool fcDirectiveLine(FcCtx* c, FcSlice line, const char** name, FcSlice* argument, bool* hasArgument) {
    int i = 0, start;
    while (i < line.n && fcIsWhiteSpace(line.p[i])) i++;
    if (i >= line.n || line.p[i] != '#') return false;
    i++;
    if (i >= line.n || !fcIsNameStart(line.p[i])) return false;
    start = i;
    while (i < line.n && fcIsNamePart(line.p[i])) i++;
    *name = fc8FromU16(c, line.p + start, i - start);
    *hasArgument = false;
    argument->p = line.p + line.n;
    argument->n = 0;
    if (i < line.n && (line.p[i] == ' ' || line.p[i] == '\t')) {
        while (i < line.n && (line.p[i] == ' ' || line.p[i] == '\t')) i++;
        *hasArgument = true;
        argument->p = line.p + i;
        argument->n = line.n - i;
        return true;
    }
    for (; i < line.n; i++) if (!fcIsWhiteSpace(line.p[i])) return false;
    return true;
}

/* `^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$` */
static bool fcUsingName(FcSlice s) {
    int i = 0;
    for (;;) {
        if (i >= s.n || !fcIsNameStart(s.p[i])) return false;
        i++;
        while (i < s.n && fcIsNamePart(s.p[i])) i++;
        if (i == s.n) return true;
        if (s.p[i] != '.') return false;
        i++;
    }
}

/* ---- paths (Path.GetFullPath, Path.Combine, Path.GetDirectoryName) ---- */
static bool fcIsSep(char ch) {
#ifdef _WIN32
    return ch == '/' || ch == '\\';
#else
    return ch == '/';
#endif
}
static const char* fcFullPath(FcCtx* c, const char* basePath, const char* path) {
    FcBuf joined = {0};
    const char** parts;
    int count = 0, i;
    const char* p;
    FcBuf out = {0};
#ifdef _WIN32
    /* (Windows: a path with its drive is rooted; the result is C:/a/b) */
    char drive[3] = { 0, 0, 0 };
    bool rooted = fcIsSep(path[0]) || (path[0] && path[1] == ':');
    if (!rooted) {
        if (!(fcIsSep(basePath[0]) || (basePath[0] && basePath[1] == ':'))) {
            char cwd[4096];
            if (!_getcwd(cwd, sizeof cwd)) strcpy(cwd, ".");
            fcBufStr(&joined, cwd);
            fcBufChar(&joined, '/');
        }
        fcBufStr(&joined, basePath);
        fcBufChar(&joined, '/');
    }
    fcBufStr(&joined, path);
    if (joined.p[0] && joined.p[1] == ':') { drive[0] = joined.p[0]; drive[1] = ':'; joined.p[0] = '/'; joined.p[1] = '/'; }
    else if (fcIsSep(joined.p[0])) {
        char cwd[8];
        if (_getcwd(cwd, sizeof cwd) && cwd[1] == ':') { drive[0] = cwd[0]; drive[1] = ':'; }   /* (\x: the drive of the working folder) */
    }
#else
    if (!fcIsSep(path[0])) {
        if (!fcIsSep(basePath[0])) {
            char cwd[4096];
#ifdef _WIN32
            if (!_getcwd(cwd, sizeof cwd)) strcpy(cwd, ".");
#else
            if (!getcwd(cwd, sizeof cwd)) strcpy(cwd, ".");
#endif
            fcBufStr(&joined, cwd);
            fcBufChar(&joined, '/');
        }
        fcBufStr(&joined, basePath);
        fcBufChar(&joined, '/');
    }
    fcBufStr(&joined, path);
#endif
    parts = (const char**)fcAlloc(c, sizeof(char*) * (joined.len + 1));
    for (p = joined.p; *p;) {
        const char* s;
        while (*p && fcIsSep(*p)) p++;
        s = p;
        while (*p && !fcIsSep(*p)) p++;
        if (p == s) break;
        if (p - s == 1 && s[0] == '.') continue;
        if (p - s == 2 && s[0] == '.' && s[1] == '.') { if (count > 0) count--; continue; }
        parts[count++] = fcStrN(c, s, (size_t)(p - s));
    }
    fcBufStr(&out, "");
#ifdef _WIN32
    fcBufStr(&out, drive);
#endif
    for (i = 0; i < count; i++) { fcBufChar(&out, '/'); fcBufStr(&out, parts[i]); }
    if (count == 0) fcBufChar(&out, '/');
    fcBufFree(&joined);
    return fcBufDone(c, &out);
}
/* the root of a file system: "/" (Windows: "C:/", "C:" as well) */
static bool fcIsRootDir(const char* p) {
#ifdef _WIN32
    if (p[0] && p[1] == ':' && (!p[2] || (fcIsSep(p[2]) && !p[3]))) return true;
#endif
    return fcIsSep(p[0]) && !p[1];
}
static const char* fcDirectoryName(FcCtx* c, const char* fullPath) {
    const char* last = NULL;
    const char* p;
    for (p = fullPath; *p; p++) if (fcIsSep(*p)) last = p;
#ifdef _WIN32
    /* (the drive: C:/a -> C:/, C:/ stays) */
    if (fullPath[0] && fullPath[1] == ':' && (!last || last == fullPath + 2)) return fcFmt(c, "%.2s/", fullPath);
#endif
    if (!last) return ".";
    if (last == fullPath) return "/";
    return fcStrN(c, fullPath, (size_t)(last - fullPath));
}
static bool fcFileExists(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) return false;
    fclose(f);
    return true;
}

static void fcProcessInner(FcPreprocessor* pp, const uint16_t* source, int length, const char* basePath, FcU16* out);
/* the markup generators (MarkupFiles in biscuitgenerator.c, after the frontend in forge.c) */
static bool fmIsGenerated(const char* path);
static const char* fmGenerateScript(FcCtx* c, const char* path, const uint16_t* text, int n);
static const char* fmBaseNameOf(const char* path) {
    const char* last = path;
    const char* p;
    for (p = path; *p; p++) if (*p == '/' || *p == '\\') last = p + 1;
    return last;
}

/* Preprocessor.ProcessFileRecursive */
static void fcProcessFileRecursive(FcPreprocessor* pp, const char* fullPath, FcU16* out) {
    FcCtx* c = pp->ctx;
    FcU16 text = {0};
    const uint16_t* copy;
    int n;
    if (fcListHasIStr(pp->includeChain, fullPath)) {
        FcBuf chain = {0};
        int i;
        fcBufStr(&chain, "");
        for (i = 0; i < pp->includeChain->count; i++) { if (i) fcBufStr(&chain, " -> "); fcBufStr(&chain, (const char*)pp->includeChain->items[i]); }
        fcPreError(c, fcFmt(c, "Circular include of '%s' (chain: %s -> %s).", fullPath, fcBufDone(c, &chain), fullPath));
    }
    if (!fcReadText(fullPath, &text)) fcPreError(c, fcFmt(c, "'%s' could not be read: %s", fullPath, "the file cannot be opened"));
    n = text.len;
    copy = (const uint16_t*)fcAlloc(c, sizeof(uint16_t) * (size_t)(n + 1));
    if (n) memcpy((void*)copy, text.p, sizeof(uint16_t) * (size_t)n);
    fcU16Free(&text);
    /* a markup file of a user interface (docs/ui/markup.md) or a schematic (`.biscuit`, docs/circuits/README.md) is included as the script generated from it */
    if (fmIsGenerated(fullPath)) {
        const char* volatile script = NULL;
        FcU16 generated = {0};
        FC_TRY(c) {
            script = fmGenerateScript(c, fullPath, copy, n);
        } FC_CATCH(c) {
            if (c->err.kind != FC_ERR_MARKUP) fcRethrow(c);
            fcPreError(c, fcFmt(c, "'%s': %s", fmBaseNameOf(fullPath), c->err.message));
        } FC_END_TRY;
        n = fcU16FromFc8(script, &generated);
        copy = (const uint16_t*)fcAlloc(c, sizeof(uint16_t) * (size_t)(n + 1));
        if (n) memcpy((void*)copy, generated.p, sizeof(uint16_t) * (size_t)n);
        fcU16Free(&generated);
    }
    fcListAdd(c, pp->includeChain, (void*)fullPath);
    fcProcessInner(pp, copy, n, fcDirectoryName(c, fullPath), out);
    pp->includeChain->count--;
}

static const char* fcValueKindName(FcTokenType t) {
    switch (t) {
        case TT_StringLiteral: return "String";
        case TT_IntLiteral: return "Int";
        case TT_FloatLiteral: return "Float";
        case TT_CharLiteral: return "Char";
        case TT_True: case TT_False: return "Bool";
        default: return "Undefined";
    }
}

static void fcLexDirectiveArgs(FcCtx* c, FcSlice argText, const char* defName, int line, FcTokens* out) {
    FC_TRY(c) {
        *out = fcTokenize(c, argText.p, argText.n);
    } FC_CATCH(c) {
        if (c->err.kind != FC_ERR_LEX) fcRethrow(c);
        fcPreError(c, fcFmt(c, "Invalid parameters for '#%s' (line %d): %s (%d:%d)", defName, line, c->err.message, c->err.line, c->err.column));
    } FC_END_TRY;
}

/* ParseDirectiveArgs + ReadDirectiveLiteral: the tokens of the values (the kind of a value is all a handler here asks) */
static FcList* fcParseDirectiveArgs(FcCtx* c, FcSlice argText, const char* defName, int paramCount, int line) {
    FcTokens tokens;
    FcList* values = fcListNew(c);
    int i = 0;
    if (paramCount == 0) {
        if (fcSliceTrim(argText).n > 0) fcPreError(c, fcFmt(c, "'#%s' expects no parameters (line %d).", defName, line));
        return values;
    }
    fcLexDirectiveArgs(c, argText, defName, line, &tokens);
    while (i < tokens.count && tokens.items[i].type != TT_Eof) {
        FcToken* tok = &tokens.items[i];
        switch (tok->type) {
            case TT_StringLiteral: case TT_IntLiteral: case TT_FloatLiteral: case TT_CharLiteral: case TT_True: case TT_False: case TT_Undefined:
                fcListAdd(c, values, tok);
                i++;
                break;
            case TT_Minus:
                i++;
                if (i >= tokens.count || (tokens.items[i].type != TT_IntLiteral && tokens.items[i].type != TT_FloatLiteral))
                    fcPreError(c, fcFmt(c, "Expected a number after '-' in the parameters of '#%s' (line %d).", defName, line));
                fcListAdd(c, values, &tokens.items[i]);
                i++;
                break;
            default:
                fcPreError(c, fcFmt(c, "Expected a literal value (string/number/char/bool/undefined) in the parameters of '#%s', not '%s' (line %d).",
                    defName, tok->lexeme, line));
        }
        if (i < tokens.count && tokens.items[i].type == TT_Comma) { i++; continue; }
        break;
    }
    if (i < tokens.count && tokens.items[i].type != TT_Eof)
        fcPreError(c, fcFmt(c, "Unexpected token '%s' in the parameters of '#%s' (line %d).", tokens.items[i].lexeme, defName, line));
    if (values->count != paramCount)
        fcPreError(c, fcFmt(c, "'#%s' expects %d parameters, got %d (line %d).", defName, paramCount, values->count, line));
    return values;
}

/* the handler of `#include` (DirectiveRegistry.CreateDefault) */
static void fcIncludeHandler(FcPreprocessor* pp, const char* basePath, FcList* args, int line, FcU16* out) {
    FcCtx* c = pp->ctx;
    FcToken* arg = (FcToken*)args->items[0];
    const char* relativePath;
    const char* fullPath;
    if (arg->type != TT_StringLiteral)
        fcPreError(c, fcFmt(c, "'#include' expects a string as the path, not %s (line %d).", fcValueKindName(arg->type), line));
    relativePath = arg->stringValue;
    fullPath = fcFullPath(c, basePath, relativePath);
    if (fcListHasIStr(pp->alreadyIncluded, fullPath)) return;   /* already inserted (anywhere in the whole composition) */
    fcListAdd(c, pp->alreadyIncluded, (void*)fullPath);
    if (!fcFileExists(fullPath))
        fcPreError(c, fcFmt(c, "'#include \"%s\"' - file not found: '%s' (line %d).", relativePath, fullPath, line));
    fcProcessFileRecursive(pp, fullPath, out);
}

/* Preprocessor.IsCode: the index is not in a string or behind `//` */
static bool fcIsCodeAt(const uint16_t* line, int n, int index) {
    bool inString = false;
    int i;
    for (i = 0; i < index; i++) {
        uint16_t ch = line[i];
        if (inString) { if (ch == '\\') i++; else if (ch == '"') inString = false; }
        else if (ch == '"') inString = true;
        else if (ch == '/' && i + 1 < n && line[i + 1] == '/') return false;
    }
    return !inString;
}
static bool fcIsWordUnit(uint16_t ch) { return fcIsLetterOrDigit(ch) || ch == '_'; }
static bool fcIsRegexSpace(uint16_t ch) { return ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' || ch == '\f' || ch == '\v' || fcIsWhiteSpace(ch); }
/* Preprocessor.ResolveResources: `new Resource("path")` in the code of a line becomes `new Resource(<id>)` (the regex
 * \bnew\s+Resource\s*\(\s*"((?:[^"\\]|\\.)*)"\s*\)) */
static void fcResolveResources(FcCtx* c, FcSlice line, const char* basePath, int lineNo, FcU16* out) {
    static const uint16_t kResource[] = { 'R', 'e', 's', 'o', 'u', 'r', 'c', 'e' };
    const uint16_t* p = line.p;
    int n = line.n, i = 0, copied = 0;
    while (i + 3 <= n) {
        int j, strStart, strEnd;
        if (!(p[i] == 'n' && p[i + 1] == 'e' && p[i + 2] == 'w' && (i == 0 || !fcIsWordUnit(p[i - 1])) && (i + 3 >= n || !fcIsWordUnit(p[i + 3])))) { i++; continue; }
        j = i + 3;
        if (j >= n || !fcIsRegexSpace(p[j])) { i++; continue; }
        while (j < n && fcIsRegexSpace(p[j])) j++;
        if (j + 8 > n || memcmp(p + j, kResource, sizeof kResource) != 0) { i++; continue; }
        j += 8;
        while (j < n && fcIsRegexSpace(p[j])) j++;
        if (j >= n || p[j] != '(') { i++; continue; }
        j++;
        while (j < n && fcIsRegexSpace(p[j])) j++;
        if (j >= n || p[j] != '"') { i++; continue; }
        strStart = ++j;
        while (j < n && p[j] != '"') { if (p[j] == '\\') { if (j + 1 >= n) break; j += 2; } else j++; }
        if (j >= n || p[j] != '"') { i++; continue; }
        strEnd = j++;
        while (j < n && fcIsRegexSpace(p[j])) j++;
        if (j >= n || p[j] != ')') { i++; continue; }
        j++;
        if (fcIsCodeAt(p, n, i)) {
            /* Regex.Unescape of the path */
            FcU16 path = {0};
            const char* rel;
            const char* full;
            int k, id = -1;
            char num[32];
            for (k = strStart; k < strEnd; k++) {
                uint16_t ch = p[k];
                if (ch == '\\' && k + 1 < strEnd) {
                    uint16_t e = p[++k];
                    fcU16Unit(&path, e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e);
                } else fcU16Unit(&path, ch);
            }
            rel = fc8FromU16(c, path.p, path.len);
            fcU16Free(&path);
            full = fcFullPath(c, basePath, rel);
            if (!fcFileExists(full)) fcPreError(c, fcFmt(c, "Resource file not found: '%s' ('%s', line %d).", rel, full, lineNo));
            for (k = 0; k < c->resourcePaths->count; k++) if (strcmp((const char*)c->resourcePaths->items[k], full) == 0) id = k;
            if (id < 0) {
                fcResourceAdded(c, full, rel);   /* (a model becomes fire's model file now: Phase D 4) */
                id = c->resourcePaths->count; fcListAdd(c, c->resourcePaths, (void*)full); if (c->resourceNames) fcListAdd(c, c->resourceNames, (void*)rel);
            }
            fcU16Put(out, p + copied, i - copied);
            snprintf(num, sizeof num, "new Resource(%d)", id);
            for (k = 0; num[k]; k++) fcU16Unit(out, (uint16_t)num[k]);
            copied = j;
        }
        i = j;
    }
    fcU16Put(out, p + copied, n - copied);
}

static bool fcU16EndsWithNewline(const FcU16* b, int from) { return b->len > from && b->p[b->len - 1] == '\n'; }

static void fcProcessInner(FcPreprocessor* pp, const uint16_t* source, int length, const char* basePath, FcU16* out) {
    FcCtx* c = pp->ctx;
    FcCondState conditional = {0};
    FcInlineCScan inlineC = {0};
    int lineStart = 0, lineNo = 0;
    for (;;) {
        int end = lineStart;
        FcSlice line;
        const char* name;
        FcSlice argument;
        bool hasArgument, match;
        while (end < length && source[end] != '\n') end++;
        line.p = source + lineStart;
        line.n = end - lineStart;
        while (line.n > 0 && line.p[line.n - 1] == '\r') line.n--;
        if (fcInlineInBody(&inlineC)) {
            fcInlineFeed(&inlineC, line);
            fcU16Put(out, line.p, line.n);
            fcU16Unit(out, '\n');
            goto next;
        }
        match = fcDirectiveLine(c, line, &name, &argument, &hasArgument);
        if (!match && fcCondActive(&conditional)) fcInlineFeed(&inlineC, line);
        if (!match) {
            if (fcCondActive(&conditional)) {
                if (c->resourcePaths) fcResolveResources(c, line, basePath, lineNo + 1, out);
                else fcU16Put(out, line.p, line.n);
            }
            fcU16Unit(out, '\n');
            goto next;
        }
        if (fcCondTryHandle(c, &conditional, name, argument, lineNo + 1, c->symbols)) { fcU16Unit(out, '\n'); goto next; }
        if (!fcCondActive(&conditional)) { fcU16Unit(out, '\n'); goto next; }
        if (fcAsciiIEq(name, "using")) {
            FcSlice usingArg = fcSliceTrim(argument);
            if (!fcUsingName(usingArg))
                fcPreError(c, fcFmt(c, "'#using' expects a (possibly dotted) namespace name, not '%s' (line %d).", fcSliceText(c, usingArg), lineNo + 1));
            fcListAdd(c, pp->usings, (void*)fcSliceText(c, usingArg));
            fcU16Unit(out, '\n');
            goto next;
        }
        {
            size_t k;
            const FcDirectiveDef* def = NULL;
            for (k = 0; k < sizeof fcDirectives / sizeof fcDirectives[0]; k++) if (fcAsciiIEq(name, fcDirectives[k].name)) def = &fcDirectives[k];
            if (!def) { fcU16Put(out, line.p, line.n); fcU16Unit(out, '\n'); goto next; }
            {
                FcList* args = fcParseDirectiveArgs(c, argument, def->name, def->paramCount, lineNo + 1);
                int before = out->len;
                if (strcmp(def->name, "include") == 0) fcIncludeHandler(pp, basePath, args, lineNo + 1, out);
                else if (c->directiveHook) c->directiveHook(c, c->directiveState, def->name, args, lineNo + 1, pp->importNamespaces);
                if (out->len > before) { if (!fcU16EndsWithNewline(out, before)) fcU16Unit(out, '\n'); }
                else fcU16Unit(out, '\n');
            }
        }
    next:
        lineNo++;
        if (end >= length) break;
        lineStart = end + 1;
    }
    fcCondEnsureClosed(c, &conditional);
    free(conditional.frames);
}

/* fcProcessInner, and on an exception the buffer freed (an error of a directive's handler, Phase C 3) */
static void fcProcessGuarded(FcPreprocessor* pp, const uint16_t* source, int length, const char* basePath, FcU16* out) {
    FcCtx* c = pp->ctx;
    FC_TRY(c) {
        fcProcessInner(pp, source, length, basePath, out);
    } FC_CATCH(c) {
        fcU16Free(out);
        fcRethrow(c);
    } FC_END_TRY;
}

/* Preprocessor.Process(source, basePath, registry): the default registry with the symbols of the context */
FcProcessed* fcPreprocess(FcCtx* c, const uint16_t* source, int length, const char* basePath) {
    FcPreprocessor pp;
    FcU16 out = {0};
    FcProcessed* r = (FcProcessed*)fcAlloc(c, sizeof *r);
    uint16_t* copy;
    int i;
    pp.ctx = c;
    pp.includeChain = fcListNew(c);
    pp.usings = fcListNew(c);
    pp.importNamespaces = fcListNew(c);
    pp.alreadyIncluded = c->sharedIncluded ? c->sharedIncluded : fcListNew(c);
    fcU16Put(&out, NULL, 0);
    fcProcessGuarded(&pp, source, length, basePath, &out);
    copy = (uint16_t*)fcAlloc(c, sizeof(uint16_t) * (size_t)(out.len + 1));
    if (out.len) memcpy(copy, out.p, sizeof(uint16_t) * (size_t)out.len);
    r->source = copy;
    r->length = out.len;
    fcU16Free(&out);
    r->usings = pp.usings;
    for (i = 0; i < pp.importNamespaces->count; i++)
        if (!fcListHasStr(r->usings, (const char*)pp.importNamespaces->items[i])) fcListAdd(c, r->usings, pp.importNamespaces->items[i]);
    r->importNamespaces = pp.importNamespaces;
    return r;
}
/* ---- (native/forge/preprocessor.c ends: native/forge/forge.c) ---- */
/* ---- native/forge/units.c ---- */
/* native/forge/units.c - the part of src/fire/Values/Unit.cs (commit a3e43117) that the parser needs: Unit.Parse (dimensions, scale, offset,
 * conversion functions; the names only as far as a literal shows them), CaretExponents, NiceFactor, the units of the program (CustomUnit,
 * UseCustomUnits, IsCustomUnitWord, BuiltInMeaning). Texts are fc8. */

#define FC_MAX_DIMS 16
typedef struct FcUnit {
    int dimCount;
    const char* dimSym[FC_MAX_DIMS];
    int dimExp[FC_MAX_DIMS];
    double scale, offset;
    const char* converter;
    const char* unitlessConverter;
} FcUnit;

struct FcCustomUnit {
    const char* name;
    const char* symbol;
    bool prefixed;
    FcUnit unit;   /* its dimensions, scale, offset, converter, unitless converter */
};

typedef struct FcNamedUnit { const char* symbol; const char* base; int exponent; double scale; } FcNamedUnit;
static const FcNamedUnit fcNamedUnits[] = {
    {"m", "m", 1, 1.0}, {"g", "g", 1, 1.0}, {"s", "s", 1, 1.0}, {"b", "b", 1, 1.0}, {"B", "b", 1, 8.0}, {"l", "m", 3, 0.001},
    {"min", "s", 1, 60.0}, {"h", "s", 1, 3600.0}, {"d", "s", 1, 86400.0},
};

static const FcNamedUnit* fcNamed(const char* s) {
    size_t i;
    for (i = 0; i < sizeof fcNamedUnits / sizeof fcNamedUnits[0]; i++) if (strcmp(fcNamedUnits[i].symbol, s) == 0) return &fcNamedUnits[i];
    return NULL;
}
static bool fcPrefixableBase(const char* s) { return !strcmp(s, "m") || !strcmp(s, "g") || !strcmp(s, "s") || !strcmp(s, "b") || !strcmp(s, "B") || !strcmp(s, "l"); }
static bool fcNonPrefixable(const char* s) { return !strcmp(s, "min") || !strcmp(s, "h") || !strcmp(s, "d"); }

/* the first UTF-16 unit of an fc8 text and the text behind it */
static uint16_t fc8First(const char* s, const char** rest) {
    const unsigned char* p = (const unsigned char*)s;
    uint16_t u = fc8Next(&p);
    *rest = (const char*)p;
    return u;
}

/* Unit.Prefixes */
static bool fcPrefix(uint16_t c, double* factor) {
    switch (c) {
        case 'f': *factor = 1e-15; return true;
        case 'p': *factor = 1e-12; return true;
        case 'n': *factor = 1e-9; return true;
        case 0xB5: case 0x3BC: case 'u': *factor = 1e-6; return true;
        case 'm': *factor = 1e-3; return true;
        case 'c': *factor = 1e-2; return true;
        case 'd': *factor = 1e-1; return true;
        case 'h': *factor = 1e2; return true;
        case 'k': *factor = 1e3; return true;
        case 'M': *factor = 1e6; return true;
        case 'G': *factor = 1e9; return true;
        default: return false;
    }
}
static bool fcPrefixAllowed(uint16_t prefix, const char* symbol) {
    return !((prefix == 'd' || prefix == 'h') && (!strcmp(symbol, "b") || !strcmp(symbol, "B")));
}

static bool fcIsUnitLetter(uint16_t c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == 0xB5 || c == 0x3BC; }

/* Unit.CaretExponents */
static const char* fcCaretExponents(FcCtx* c, const char* text) {
    FcBuf b = {0};
    const unsigned char* p = (const unsigned char*)text;
    uint16_t prev = 0;
    bool any = false, first = true;
    fcBufStr(&b, "");
    while (*p) {
        uint16_t u = fc8Next(&p);
        if (u >= '0' && u <= '9' && !first && fcIsUnitLetter(prev)) { fcBufChar(&b, '^'); any = true; }
        fcBufUnit(&b, u);
        prev = u;
        first = false;
    }
    if (!any) { fcBufFree(&b); return text; }
    return fcBufDone(c, &b);
}

/* Unit.NiceFactor: a factor a few units in the last place away from a number with 12 significant digits is that number */
static double fcNiceFactor(double factor) {
    char t[64];
    double nice;
    snprintf(t, sizeof t, "%.12g", factor);
    nice = strtod(t, NULL);
    return fabs(nice - factor) <= 8 * 2.220446049250313e-16 * fabs(factor) ? nice : factor;
}

/* .NET's ToString("G10") of a double */
static const char* fcG10(FcCtx* c, double v) {
    char t[64];
    char* p;
    if (isnan(v)) return "NaN";
    if (isinf(v)) return v > 0 ? "\xE2\x88\x9E" : "-\xE2\x88\x9E";
    snprintf(t, sizeof t, "%.10g", v);
    for (p = t; *p; p++) if (*p == 'e') *p = 'E';
    return fcStr(c, t);
}

static void fcUnitSetUnitless(FcUnit* u) { memset(u, 0, sizeof *u); u->scale = 1.0; }
static bool fcUnitIsUnitless(const FcUnit* u) { return u->dimCount == 0; }
static int fcUnitDim(const FcUnit* u, const char* sym) {
    int i;
    for (i = 0; i < u->dimCount; i++) if (strcmp(u->dimSym[i], sym) == 0) return i;
    return -1;
}
static void fcUnitAddDim(FcUnit* u, const char* sym, int exp) {
    int i = fcUnitDim(u, sym);
    if (i < 0) {
        if (u->dimCount == FC_MAX_DIMS) return;
        u->dimSym[u->dimCount] = sym;
        u->dimExp[u->dimCount] = exp;
        u->dimCount++;
        i = u->dimCount - 1;
    } else u->dimExp[i] += exp;
    if (u->dimExp[i] == 0) {
        for (; i + 1 < u->dimCount; i++) { u->dimSym[i] = u->dimSym[i + 1]; u->dimExp[i] = u->dimExp[i + 1]; }
        u->dimCount--;
    }
}
static bool fcUnitCompatible(const FcUnit* a, const FcUnit* b) {
    int i;
    if (a->dimCount != b->dimCount) return false;
    for (i = 0; i < a->dimCount; i++) {
        int k = fcUnitDim(b, a->dimSym[i]);
        if (k < 0 || b->dimExp[k] != a->dimExp[i]) return false;
    }
    return true;
}
static bool fcSameOptText(const char* a, const char* b) { return a == b || (a && b && strcmp(a, b) == 0); }
static bool fcUnitEquals(const FcUnit* a, const FcUnit* b) {
    return fcUnitCompatible(a, b) && fabs(a->scale - b->scale) < 1e-12 && a->offset == b->offset && fcSameOptText(a->converter, b->converter)
        && fcSameOptText(a->unitlessConverter, b->unitlessConverter);
}

static FcCustomUnit* fcCustomFind(FcCtx* c, const char* key) { return (FcCustomUnit*)fbMapGet(&c->customTable, key); }

/* Unit.UseCustomUnits */
static void fcUseCustomUnits(FcCtx* c, FcList* units) {
    int i;
    fbMapFree(&c->customTable);
    c->customUnits = fcListNew(c);
    if (!units) return;
    for (i = 0; i < units->count; i++) {
        FcCustomUnit* u = (FcCustomUnit*)units->items[i];
        fcListAdd(c, c->customUnits, u);
        fbMapPut(&c->customTable, u->symbol, u);
        if (strcmp(u->name, u->symbol) != 0 && !fbMapHas(&c->customTable, u->name)) fbMapPut(&c->customTable, u->name, u);
    }
}

/* Unit.IsCustomUnitWord */
static bool fcIsCustomUnitWord(FcCtx* c, const char* word) {
    const char* rest;
    uint16_t first;
    double factor;
    FcCustomUnit* u;
    if (fcCustomFind(c, word)) return true;
    if (fc8Units(word) < 2) return false;
    first = fc8First(word, &rest);
    if (!fcPrefix(first, &factor)) return false;
    u = fcCustomFind(c, rest);
    return u && u->prefixed && strcmp(u->symbol, rest) == 0 && fcPrefixAllowed(first, u->symbol);
}

/* Unit.BuiltInMeaning */
static const char* fcBuiltInMeaning(const char* word) { return fcNamed(word) ? word : NULL; }

static bool fcTryBuiltIn(const char* symbol, FcUnit* unit) {
    const FcNamedUnit* named = fcNamed(symbol);
    fcUnitSetUnitless(unit);
    if (named) { fcUnitAddDim(unit, named->base, named->exponent); unit->scale = named->scale; return true; }
    if (fc8Units(symbol) >= 2) {
        const char* rest;
        uint16_t first = fc8First(symbol, &rest);
        double factor;
        const FcNamedUnit* base = fcNamed(rest);
        if (fcPrefix(first, &factor) && base && fcPrefixableBase(rest) && !fcNonPrefixable(rest) && fcPrefixAllowed(first, rest)) {
            fcUnitAddDim(unit, base->base, base->exponent);
            unit->scale = factor * base->scale;
            return true;
        }
    }
    return false;
}

static void fcUnitParseWith(FcCtx* c, const char* symbol, FcUnit* out);

static void fcUnitMultiply(FcUnit* result, const FcUnit* aIn, const FcUnit* bIn, bool divide) {
    FcUnit a = *aIn, b = *bIn, r;
    int i;
    if (a.unitlessConverter) fcUnitSetUnitless(&a);
    if (b.unitlessConverter) fcUnitSetUnitless(&b);
    if (fcUnitIsUnitless(&b)) { *result = a; return; }
    if (!divide && fcUnitIsUnitless(&a)) { *result = b; return; }
    r = a;
    r.offset = 0; r.converter = NULL; r.unitlessConverter = NULL;
    for (i = 0; i < b.dimCount; i++) fcUnitAddDim(&r, b.dimSym[i], divide ? -b.dimExp[i] : b.dimExp[i]);
    r.scale = divide ? a.scale / b.scale : a.scale * b.scale;
    *result = r;
}

/* Unit.ParseCombined (knownOnly: false) - the dimensions and the scale; the result is linear */
static void fcUnitParseCombined(FcCtx* c, const char* symbol, FcUnit* out) {
    FcUnit result;
    bool divide = false;
    size_t i = 0, n = strlen(symbol);
    fcUnitSetUnitless(&result);
    while (i < n) {
        size_t start = i;
        FcUnit factor;
        int power = 1, p;
        while (i < n && symbol[i] != '/' && symbol[i] != '*' && symbol[i] != '^') i++;
        fcUnitParseWith(c, fcStrN(c, symbol + start, i - start), &factor);
        if (i < n && symbol[i] == '^') {
            size_t numberStart = ++i;
            bool neg = false;
            int v = 0;
            if (i < n && symbol[i] == '-') { neg = true; i++; }
            while (i < n && symbol[i] >= '0' && symbol[i] <= '9') v = v * 10 + (symbol[i++] - '0');
            (void)numberStart;
            power = neg ? -v : v;
        }
        for (p = 0; p < abs(power); p++) fcUnitMultiply(&result, &result, &factor, divide ^ (power < 0));
        if (i < n) {
            if (symbol[i] == '/') divide = true;
            i++;
        }
    }
    *out = result;
    out->offset = 0; out->converter = NULL; out->unitlessConverter = NULL;
}

static void fcUnitParseWith(FcCtx* c, const char* symbol, FcUnit* out) {
    FcCustomUnit* own;
    fcUnitSetUnitless(out);
    if (!symbol[0]) return;
    if (strpbrk(symbol, "/*^")) { fcUnitParseCombined(c, symbol, out); return; }
    if (fcNamed(symbol) && fcTryBuiltIn(symbol, out)) return;
    if (c->customUnits->count > 0 && (own = fcCustomFind(c, symbol)) != NULL) { *out = own->unit; return; }
    if (fcTryBuiltIn(symbol, out)) return;
    if (fc8Units(symbol) >= 2 && c->customUnits->count > 0) {
        const char* rest;
        uint16_t first = fc8First(symbol, &rest);
        double factor;
        FcCustomUnit* prefixable;
        if (fcPrefix(first, &factor) && (prefixable = fcCustomFind(c, rest)) != NULL && prefixable->prefixed && strcmp(prefixable->symbol, rest) == 0
            && fcPrefixAllowed(first, prefixable->symbol)) {
            fcUnitSetUnitless(out);
            memcpy((void*)out->dimSym, (const void*)prefixable->unit.dimSym, sizeof out->dimSym);   /* (casts: MSVC warns C4090 for an array of const char*) */
            memcpy(out->dimExp, prefixable->unit.dimExp, sizeof out->dimExp);
            out->dimCount = prefixable->unit.dimCount;
            out->scale = factor * prefixable->unit.scale;
            return;
        }
    }
    fcUnitSetUnitless(out);
    fcUnitAddDim(out, symbol, 1);
}

/* Unit.Parse */
static void fcUnitParse(FcCtx* c, const char* symbol, FcUnit* out) {
    if (!symbol || !symbol[0] || strcmp(symbol, "unitless") == 0) { fcUnitSetUnitless(out); return; }
    fcUnitParseWith(c, fcCaretExponents(c, symbol), out);
}

/* the text of Unit.Parse(suffix).ToString() for the unit suffix of a number literal (NULL for unitless): fcLiteralUnitText in unitv.c */
static const char* fcLiteralUnitText(FcCtx* c, const char* suffix);
/* ---- (native/forge/units.c ends: native/forge/forge.c) ---- */
/* ---- native/forge/unitv.c ---- */
/* native/forge/unitv.c - the unit as a value of the type checker: src/fire/Values/Unit.cs (commit c7f13d97) - Parse with the name of the unit
 * (ParseWith, ParseCombined, the names of combined units: TermsOfText, MergeTerms, SimplifyTerms, RenderTerms, CombinedName), Multiply, Divide,
 * Equals, IsCompatibleWith, IsLinear, ConversionFactorTo, ToString, DemandText. The dimensions, the factor and the conversions are a FcUnit of
 * units.c; Unit.Unitless is fcUnitlessU (the same object every time, as in C#). Not ported: DecodeDemand (a demand text is no source text), the
 * caches of the last product and quotient (they only save work). */

typedef struct FcTerm { const char* sym; int exp; } FcTerm;
typedef struct FcTerms { FcTerm* items; int count, cap; } FcTerms;
typedef struct FcU { FcUnit u; const char* display; FcTerms* terms; bool termsKnown; } FcU;

static const FcU fcUnitlessU = { { 0, {0}, {0}, 1.0, 0.0, NULL, NULL }, NULL, NULL, true };
#define FC_UNITLESS ((FcU*)&fcUnitlessU)

static FcU* fcUNew(FcCtx* c, const FcUnit* u, const char* display) {
    FcU* r = (FcU*)fcAlloc(c, sizeof *r);
    r->u = *u;
    r->display = display;
    return r;
}
static bool fcUIsUnitless(const FcU* u) { return u->u.dimCount == 0; }
static bool fcUIsLinear(const FcU* u) { return u->u.offset == 0 && u->u.converter == NULL; }
static bool fcUCompatible(const FcU* a, const FcU* b) { return fcUnitCompatible(&a->u, &b->u); }
static bool fcUEquals(const FcU* a, const FcU* b) {
    if (!b || !a) return false;
    if (a == b) return true;
    return fcUnitEquals(&a->u, &b->u);
}
/* OrderBy(k => k.Key) of the dimensions: the culture's order of the texts (letters before their upper case, otherwise alphabetical) */
static int fcCultureCmp(const char* a, const char* b) {
    const unsigned char* x = (const unsigned char*)a;
    const unsigned char* y = (const unsigned char*)b;
    for (; *x && *y; x++, y++) {
        int cx = tolower(*x), cy = tolower(*y);
        if (cx != cy) return cx - cy;
    }
    if (*x || *y) return *x ? 1 : -1;
    for (x = (const unsigned char*)a, y = (const unsigned char*)b; *x && *y; x++, y++)
        if (*x != *y) return islower(*x) ? -1 : 1;
    return 0;
}
static void fcSortedDims(const FcUnit* u, int* order, bool ordinal) {
    int i, k;
    for (i = 0; i < u->dimCount; i++) order[i] = i;
    for (i = 1; i < u->dimCount; i++)
        for (k = i; k > 0; k--) {
            int c = ordinal ? strcmp(u->dimSym[order[k - 1]], u->dimSym[order[k]]) : fcCultureCmp(u->dimSym[order[k - 1]], u->dimSym[order[k]]);
            if (c <= 0) break;
            { int t = order[k]; order[k] = order[k - 1]; order[k - 1] = t; }
        }
}

/* ---- the names of combined units ---- */
static FcTerms* fcTermsNew(FcCtx* c) { return (FcTerms*)fcAlloc(c, sizeof(FcTerms)); }
static void fcTermsAdd(FcCtx* c, FcTerms* t, const char* sym, int exp) {
    if (t->count == t->cap) {
        int ncap = t->cap ? t->cap * 2 : 4;
        FcTerm* n = (FcTerm*)fcAlloc(c, sizeof(FcTerm) * (size_t)ncap);
        if (t->count) memcpy(n, t->items, sizeof(FcTerm) * (size_t)t->count);
        t->items = n; t->cap = ncap;
    }
    t->items[t->count].sym = sym;
    t->items[t->count].exp = exp;
    t->count++;
}
static FcTerms* fcTermsCopy(FcCtx* c, const FcTerms* t) {
    FcTerms* r = fcTermsNew(c);
    int i;
    for (i = 0; i < t->count; i++) fcTermsAdd(c, r, t->items[i].sym, t->items[i].exp);
    return r;
}

/* TermsOfText: NULL when the text is no product of powers of words */
static FcTerms* fcTermsOfText(FcCtx* c, const char* text) {
    FcU16 u = {0};
    FcTerms* terms = fcTermsNew(c);
    bool divide = false;
    int i = 0, n;
    fcU16FromFc8(text, &u);
    n = u.len;
    for (;;) {
        int start = i, power = 1;
        const char* word;
        while (i < n && fcIsUnitLetter(u.p[i])) i++;
        word = fc8FromU16(c, u.p + start, i - start);
        if (i == start) {
            if (divide || terms->count > 0 || i >= n || u.p[i] != '1' || i + 1 >= n || u.p[i + 1] != '/') { fcU16Free(&u); return NULL; }
            i++;
        } else if (i < n && u.p[i] == '^') {
            int numberStart = ++i;
            bool neg = false, any = false;
            long long v = 0;   /* (not long: 32 bits on Windows) */
            if (i < n && u.p[i] == '-') i++;
            while (i < n && u.p[i] >= '0' && u.p[i] <= '9') i++;
            /* int.TryParse with a leading sign */
            {
                int k = numberStart;
                if (k < i && (u.p[k] == '-' || u.p[k] == '+')) { neg = u.p[k] == '-'; k++; }
                for (; k < i; k++) { v = v * 10 + (u.p[k] - '0'); any = true; if (v > 2147483648LL) { fcU16Free(&u); return NULL; } }
            }
            if (!any) { fcU16Free(&u); return NULL; }
            power = (int)(neg ? -v : v);
        }
        if (i > start) fcTermsAdd(c, terms, word, divide ? -power : power);
        if (i == n) { fcU16Free(&u); return terms; }
        if (u.p[i] == '/') divide = true;
        else if (u.p[i] != '*') { fcU16Free(&u); return NULL; }
        i++;
    }
}
static FcTerms* fcMergeTerms(FcCtx* c, FcTerms* terms, const FcTerms* more, int sign) {
    int i, k;
    for (i = 0; i < more->count; i++) {
        const char* sym = more->items[i].sym;
        int exp = more->items[i].exp;
        int at = -1;
        for (k = 0; k < terms->count; k++) if (strcmp(terms->items[k].sym, sym) == 0) { at = k; break; }
        if (at < 0) fcTermsAdd(c, terms, sym, sign * exp);
        else if (terms->items[at].exp + sign * exp == 0) { for (k = at; k + 1 < terms->count; k++) terms->items[k] = terms->items[k + 1]; terms->count--; }
        else terms->items[at].exp += sign * exp;
    }
    return terms;
}
static const struct { uint16_t prefix; double factor; } fcNamePrefixes[] = {
    {'f', 1e-15}, {'p', 1e-12}, {'n', 1e-9}, {0xB5, 1e-6}, {'m', 1e-3}, {'c', 1e-2}, {'d', 1e-1}, {'h', 1e2}, {'k', 1e3}, {'M', 1e6}, {'G', 1e9} };
static bool fcSplitBuiltIn(FcCtx* c, const char* sym, const char** baseSymbol, double* prefix) {
    const char* rest;
    uint16_t first;
    *baseSymbol = sym;
    *prefix = 1;
    if (fcPrefixableBase(sym)) return true;
    if (fc8Units(sym) < 2 || fcCustomFind(c, sym) || fcNamed(sym)) return false;
    first = fc8First(sym, &rest);
    if (!fcPrefixableBase(rest) || !fcPrefix(first, prefix) || !fcPrefixAllowed(first, rest)) return false;
    *baseSymbol = rest;
    return true;
}
static FcTerms* fcSimplifyTerms(FcCtx* c, FcTerms* terms) {
    int n = terms->count, k, j;
    const char** bases = (const char**)fcAlloc(c, sizeof(char*) * (size_t)(n + 1));
    double* prefixes = (double*)fcAlloc(c, sizeof(double) * (size_t)(n + 1));
    bool* drop = (bool*)fcAlloc(c, sizeof(bool) * (size_t)(n + 1));
    double factor = 1;
    bool any = false;
    for (k = 0; k < n; k++) { const char* b; double p; if (fcSplitBuiltIn(c, terms->items[k].sym, &b, &p)) { bases[k] = b; prefixes[k] = p; } }
    for (k = 0; k < n; k++) {
        int sum = 0, count = 0;
        if (!bases[k] || drop[k]) continue;
        for (j = k; j < n; j++) if (bases[j] && strcmp(bases[j], bases[k]) == 0) { sum += terms->items[j].exp; count++; }
        if (sum != 0 || count < 2) continue;
        for (j = k; j < n; j++) if (bases[j] && strcmp(bases[j], bases[k]) == 0) { drop[j] = true; factor *= pow(prefixes[j], terms->items[j].exp); }
        any = true;
    }
    if (!any) return terms;
    for (k = 0; k < n; k++) {
        double wanted;
        const char* sym;
        size_t q;
        FcTerms* result;
        if (drop[k] || !bases[k] || fcNonPrefixable(bases[k])) continue;
        wanted = prefixes[k] * pow(factor, 1.0 / terms->items[k].exp);
        sym = fabs(wanted - 1) <= 1e-9 ? bases[k] : NULL;
        for (q = 0; q < sizeof fcNamePrefixes / sizeof fcNamePrefixes[0]; q++)
            if (!sym && fabs(wanted / fcNamePrefixes[q].factor - 1) <= 1e-9 && fcPrefixAllowed(fcNamePrefixes[q].prefix, bases[k])) {
                FcBuf b = {0};
                fcBufUnit(&b, fcNamePrefixes[q].prefix);
                fcBufStr(&b, bases[k]);
                sym = fcBufDone(c, &b);
            }
        if (!sym) continue;
        result = fcTermsNew(c);
        for (j = 0; j < n; j++) if (!drop[j]) fcTermsAdd(c, result, j == k ? sym : terms->items[j].sym, terms->items[j].exp);
        return fcMergeTerms(c, fcTermsNew(c), result, 1);
    }
    return terms;
}
static const char* fcRenderTerms(FcCtx* c, const FcTerms* terms) {
    FcBuf b = {0};
    bool allNeg = true, first = true;
    int i;
    if (terms->count == 0) return NULL;
    for (i = 0; i < terms->count; i++) if (terms->items[i].exp >= 0) allNeg = false;
    fcBufStr(&b, "");
    if (allNeg) {
        for (i = 0; i < terms->count; i++) { if (b.len > 0) fcBufChar(&b, '*'); fcBufFmt(&b, "%s^%d", terms->items[i].sym, terms->items[i].exp); }
        return fcBufDone(c, &b);
    }
    for (i = 0; i < terms->count; i++)
        if (terms->items[i].exp > 0) { if (b.len > 0) fcBufChar(&b, '*'); fcBufStr(&b, terms->items[i].sym); if (terms->items[i].exp != 1) fcBufFmt(&b, "^%d", terms->items[i].exp); }
    if (b.len == 0) fcBufChar(&b, '1');
    for (i = 0; i < terms->count; i++)
        if (terms->items[i].exp < 0) { fcBufChar(&b, first ? '/' : '*'); first = false; fcBufStr(&b, terms->items[i].sym); if (terms->items[i].exp != -1) fcBufFmt(&b, "^%d", -terms->items[i].exp); }
    return fcBufDone(c, &b);
}
/* Terms(): of the name, or of the dimensions when the factor is 1 */
static const FcTerms* fcUTerms(FcCtx* c, const FcU* uc) {
    FcU* u = (FcU*)uc;
    if (u->termsKnown) return u->terms;
    if (u->display) u->terms = fcTermsOfText(c, u->display);
    else if (fabs(u->u.scale - 1.0) <= 1e-12) {
        int order[FC_MAX_DIMS], i;
        u->terms = fcTermsNew(c);
        fcSortedDims(&u->u, order, false);
        for (i = 0; i < u->u.dimCount; i++) fcTermsAdd(c, u->terms, u->u.dimSym[order[i]], u->u.dimExp[order[i]]);
    } else u->terms = NULL;
    u->termsKnown = true;
    return u->terms;
}
static const char* fcCombinedName(FcCtx* c, const FcU* a, const FcU* b, int sign) {
    const FcTerms* ta = fcUTerms(c, a);
    const FcTerms* tb = fcUTerms(c, b);
    if (!ta || !tb) return NULL;
    return fcRenderTerms(c, fcSimplifyTerms(c, fcMergeTerms(c, fcTermsCopy(c, ta), tb, sign)));
}
static const FcU* fcULinearPart(FcCtx* c, const FcU* u) {
    FcUnit lin;
    if (fcUIsLinear(u)) return u;
    lin = u->u;
    lin.offset = 0; lin.converter = NULL; lin.unitlessConverter = NULL;
    return fcUNew(c, &lin, NULL);
}
/* Unit.Multiply / Unit.Divide */
static const FcU* fcUMulDiv(FcCtx* c, const FcU* a, const FcU* b, bool divide) {
    FcUnit dims;
    int i;
    if (a->u.unitlessConverter) a = FC_UNITLESS;
    if (b->u.unitlessConverter) b = FC_UNITLESS;
    if (fcUIsUnitless(b)) return a;
    if (!divide && fcUIsUnitless(a)) return b;
    a = fcULinearPart(c, a);
    b = fcULinearPart(c, b);
    dims = a->u;
    for (i = 0; i < b->u.dimCount; i++) fcUnitAddDim(&dims, b->u.dimSym[i], divide ? -b->u.dimExp[i] : b->u.dimExp[i]);
    dims.scale = divide ? a->u.scale / b->u.scale : a->u.scale * b->u.scale;
    dims.offset = 0; dims.converter = NULL; dims.unitlessConverter = NULL;
    return fcUNew(c, &dims, dims.dimCount == 0 ? NULL : fcCombinedName(c, a, b, divide ? -1 : 1));
}
static const FcU* fcUMultiply(FcCtx* c, const FcU* a, const FcU* b) { return fcUMulDiv(c, a, b, false); }
static const FcU* fcUDivide(FcCtx* c, const FcU* a, const FcU* b) { return fcUMulDiv(c, a, b, true); }

static const FcU* fcUParseWith(FcCtx* c, const char* symbol);
static bool fcUTryBuiltIn(const char* symbol, FcUnit* unit) { return fcTryBuiltIn(symbol, unit); }
static const FcU* fcUParseCombined(FcCtx* c, const char* symbol) {
    const FcU* result = FC_UNITLESS;
    bool divide = false;
    size_t i = 0, n = strlen(symbol);
    FcTerms* terms;
    const char* name;
    FcUnit dims;
    while (i < n) {
        size_t start = i;
        const FcU* factor;
        int power = 1, p;
        while (i < n && symbol[i] != '/' && symbol[i] != '*' && symbol[i] != '^') i++;
        factor = fcUParseWith(c, fcStrN(c, symbol + start, i - start));
        if (i < n && symbol[i] == '^') {
            bool neg = false;
            int v = 0;
            ++i;
            if (i < n && symbol[i] == '-') { neg = true; i++; }
            while (i < n && symbol[i] >= '0' && symbol[i] <= '9') v = v * 10 + (symbol[i++] - '0');
            power = neg ? -v : v;
        }
        for (p = 0; p < abs(power); p++) result = (divide ^ (power < 0)) ? fcUDivide(c, result, factor) : fcUMultiply(c, result, factor);
        if (i < n) {
            if (symbol[i] == '/') divide = true;
            i++;
        }
    }
    terms = fcTermsOfText(c, symbol);
    name = terms == NULL ? symbol : fcRenderTerms(c, fcSimplifyTerms(c, fcMergeTerms(c, fcTermsNew(c), terms, 1)));
    if (!name) name = symbol;
    dims = result->u;
    dims.offset = 0; dims.converter = NULL; dims.unitlessConverter = NULL;
    return fcUNew(c, &dims, name);
}
static const FcU* fcUParseWith(FcCtx* c, const char* symbol) {
    FcUnit u;
    FcCustomUnit* own;
    if (!symbol[0]) return FC_UNITLESS;
    if (strpbrk(symbol, "/*^")) return fcUParseCombined(c, symbol);
    if (fcNamed(symbol) && fcUTryBuiltIn(symbol, &u)) return fcUNew(c, &u, symbol);
    if (c->customUnits->count > 0 && (own = fcCustomFind(c, symbol)) != NULL) return fcUNew(c, &own->unit, own->symbol);
    if (fcUTryBuiltIn(symbol, &u)) return fcUNew(c, &u, symbol);
    if (fc8Units(symbol) >= 2 && c->customUnits->count > 0) {
        const char* rest;
        uint16_t first = fc8First(symbol, &rest);
        double factor;
        FcCustomUnit* prefixable;
        if (fcPrefix(first, &factor) && (prefixable = fcCustomFind(c, rest)) != NULL && prefixable->prefixed && strcmp(prefixable->symbol, rest) == 0
            && fcPrefixAllowed(first, prefixable->symbol)) {
            fcUnitSetUnitless(&u);
            memcpy((void*)u.dimSym, (const void*)prefixable->unit.dimSym, sizeof u.dimSym);   /* (casts: MSVC warns C4090 for an array of const char*) */
            memcpy(u.dimExp, prefixable->unit.dimExp, sizeof u.dimExp);
            u.dimCount = prefixable->unit.dimCount;
            u.scale = factor * prefixable->unit.scale;
            return fcUNew(c, &u, symbol);
        }
    }
    fcUnitSetUnitless(&u);
    fcUnitAddDim(&u, symbol, 1);
    return fcUNew(c, &u, symbol);
}
/* Unit.Parse */
static const FcU* fcUParse(FcCtx* c, const char* symbol) {
    if (!symbol || !symbol[0] || strcmp(symbol, "unitless") == 0) return FC_UNITLESS;
    return fcUParseWith(c, fcCaretExponents(c, symbol));
}

/* .NET's shortest round-trip text of a double ("R", and "G" since .NET Core 3): the fewest digits that read back as the value, in plain notation
 * for a decimal exponent from -5 to 14, otherwise as d.dddE+xx */
static const char* fcDoubleR(FcCtx* c, double v) {
    char t[64], digits[32];
    int prec, exp10, nd, i;
    FcBuf b = {0};
    const char* m;
    if (isnan(v)) return "NaN";
    if (isinf(v)) return v > 0 ? "\xE2\x88\x9E" : "-\xE2\x88\x9E";
    if (v == 0) return signbit(v) ? "-0" : "0";
    for (prec = 1; prec <= 17; prec++) { snprintf(t, sizeof t, "%.*e", prec - 1, v); if (strtod(t, NULL) == v) break; }
    /* t: [-]d.ddde[+-]xx */
    m = t;
    if (*m == '-') { fcBufChar(&b, '-'); m++; }
    nd = 0;
    for (; *m && *m != 'e'; m++) if (*m != '.') digits[nd++] = *m;
    digits[nd] = 0;
    exp10 = atoi(m + 1);
    while (nd > 1 && digits[nd - 1] == '0') digits[--nd] = 0;
    if (exp10 >= -5 && exp10 < 15) {
        if (exp10 < 0) {
            fcBufStr(&b, "0.");
            for (i = 0; i < -exp10 - 1; i++) fcBufChar(&b, '0');
            fcBufStr(&b, digits);
        } else {
            for (i = 0; i <= exp10 || i < nd; i++) {
                if (i == exp10 + 1) fcBufChar(&b, '.');
                fcBufChar(&b, i < nd ? digits[i] : '0');
            }
        }
    } else {
        fcBufChar(&b, digits[0]);
        if (nd > 1) { fcBufChar(&b, '.'); fcBufStr(&b, digits + 1); }
        fcBufFmt(&b, "E%c%02d", exp10 < 0 ? '-' : '+', exp10 < 0 ? -exp10 : exp10);
    }
    return fcBufDone(c, &b);
}

/* Unit.ToString */
static const char* fcUText(FcCtx* c, const FcU* u) {
    FcBuf num = {0}, den = {0}, out = {0};
    int order[FC_MAX_DIMS], i, numCount = 0, denCount = 0;
    if (fcUIsUnitless(u)) return "unitless";
    if (u->display) return u->display;
    fcSortedDims(&u->u, order, false);
    fcBufStr(&num, ""); fcBufStr(&den, "");
    for (i = 0; i < u->u.dimCount; i++) {
        const char* key = u->u.dimSym[order[i]];
        int exp = u->u.dimExp[order[i]];
        if (exp > 0) { if (numCount++) fcBufChar(&num, '*'); if (exp == 1) fcBufStr(&num, key); else fcBufFmt(&num, "%s^%d", key, exp); }
        else { if (denCount++) fcBufChar(&den, '*'); if (exp == -1) fcBufStr(&den, key); else fcBufFmt(&den, "%s^%d", key, -exp); }
    }
    fcBufStr(&out, numCount > 0 ? num.p : "1");
    if (denCount > 0) { fcBufChar(&out, '/'); if (denCount > 1) fcBufFmt(&out, "(%s)", den.p); else fcBufStr(&out, den.p); }
    fcBufFree(&num); fcBufFree(&den);
    if (fabs(u->u.scale - 1.0) > 1e-12) fcBufFmt(&out, "(\xC3\x97%s)", fcDoubleR(c, u->u.scale));
    return fcBufDone(c, &out);
}

static double fcUConversionFactorTo(const FcU* from, const FcU* to) {
    if (from == to) return 1.0;
    return fcNiceFactor(from->u.scale / to->u.scale);
}

/* Unit.DemandText (the text of a declaration's unit as the compiled program keeps it) */
static const char* fcUnitDemandText(FcCtx* c, const char* unitText) {
    const unsigned char* p;
    bool custom = false;
    const FcU* u;
    int order[FC_MAX_DIMS], i;
    FcBuf b = {0};
    if (fcStartsWith(unitText, "any ")) return fcFmt(c, "any %s", fcUnitDemandText(c, unitText + 4));
    if (c->customUnits->count == 0 || !unitText[0] || fcStartsWith(unitText, "\xC2\xA7")) return unitText;
    unitText = fcCaretExponents(c, unitText);
    for (p = (const unsigned char*)unitText; ;) {
        const unsigned char* start = p;
        while (*p && *p != '/' && *p != '*' && *p != '^') p++;
        if (fcIsCustomUnitWord(c, fcStrN(c, (const char*)start, (size_t)(p - start)))) custom = true;
        if (!*p) break;
        p++;
    }
    if (!custom) return unitText;
    u = fcUParse(c, unitText);
    fcBufFmt(&b, "\xC2\xA7%s\xC2\xA7", fcUText(c, u));
    fcSortedDims(&u->u, order, true);
    for (i = 0; i < u->u.dimCount; i++) { if (i) fcBufChar(&b, ','); fcBufFmt(&b, "%s:%d", u->u.dimSym[order[i]], u->u.dimExp[order[i]]); }
    fcBufFmt(&b, "\xC2\xA7%s\xC2\xA7%s\xC2\xA7%s\xC2\xA7%s", fcDoubleR(c, u->u.scale), fcDoubleR(c, u->u.offset), u->u.converter ? u->u.converter : "",
        u->u.unitlessConverter ? u->u.unitlessConverter : "");
    return fcBufDone(c, &b);
}

/* the text of Unit.Parse(suffix).ToString() for the unit suffix of a number literal: NULL for unitless (the parser keeps a literal's unit as its text) */
static const char* fcLiteralUnitText(FcCtx* c, const char* suffix) {
    const FcU* u = fcUParse(c, suffix);
    return fcUIsUnitless(u) ? NULL : fcUText(c, u);
}
