            f = prU8(r);
            mm->isStatic = (f & 1) != 0; mm->isReadonly = (f & 2) != 0; mm->canRead = (f & 4) != 0; mm->canWrite = (f & 8) != 0;
            mm->unit = prName(r); mm->paramNames = prStrList(r); mm->paramTypes = prStrList(r);
            mm->attributes = prAttributes(r);
