    return raw > 0 ? fcFmt(g->c, "newObjectR(%s, %d, %d, %s)", ClassIdExpr(g, cls), SlotCount(g, cls), raw, owner) : fcFmt(g->c, "newObject(%s, %d, %s)", ClassIdExpr(g, cls), SlotCount(g, cls), owner);
