        pos = fmNum(m, 7, 0.5, "po");
        if (pos != 0.5) fmFSet(c, e, "position", fmFFormat(c, pos));
        /* pots linked in the XML format turn together: a group of the package */
        link = xml ? fmTok(m, 0, "li") : "";
